mapper.select:
SELECT order_id as orderId, order_no as orderNo, member_id as memberId, receiver_name as receiverName, receiver_phone as receiverPhone, receiver_address as receiverAddress, total_amount as totalAmount, status, payment_method as paymentMethod, shipping_method as shippingMethod, created_at as createdAt, updated_at as updatedAt FROM "orders"
(order_no ILIKE '%' || #{keyword} || '%' OR receiver_name ILIKE '%' || #{keyword} || '%')
AND status = #{status}
AND created_at >= CAST(#{startDate} AS TIMESTAMP)
AND created_at < CAST(#{endDate} AS TIMESTAMP) + INTERVAL '1 day'
ORDER BY created_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT order_id as orderId, order_no as orderNo, member_id as memberId,
       status, total_amount as totalAmount, created_at as createdAt
FROM "orders" WHERE order_no = #{orderNo}

mapper.update:
UPDATE "orders"
SET status = 'CANCELLED', updated_at = CURRENT_TIMESTAMP
WHERE order_no = #{orderNo}
  AND member_id = #{memberId}
  AND status IN ('pending', 'FAILED')

UPDATE "orders"
SET status = #{status}, updated_at = CURRENT_TIMESTAMP
WHERE order_no = #{orderNo}
